def fizzbuzz(n: int) -> list[str]:
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def sum_even_squares(n):
    total = 0
    for i in range(2, n + 1, 2):
        total += i * i
    return total

import re

def extract_level(line: str) -> str or None:
    levels = r"(INFO|ERROR|WARN|DEBUG)"
    match = re.search(levels, line)
    if match:
        return match.group(1)
    return None

