def flatten(d: dict) -> dict:
    """
    Flattens one level of nested dicts, joining keys with a dot.
    Non-dict values stay as they are.
    Example: {"a": {"b": 1}} -> {"a.b": 1}
             {"c": 2} -> {"c": 2}
    """
    result = {}
    for key, value in d.items():
        if isinstance(value, dict):
            # Flatten one level: join current key with nested keys
            for sub_key, sub_value in value.items():
                new_key = f"{key}.{sub_key}"
                result[new_key] = sub_value
        else:
            # Non-dict values are kept as is
            result[key] = value
    return result
