def parse_money(s: str) -> float | None:
    """
    Turns strings like "$1,234.50" or "1234.5" into a number.

    Strips a leading $ and thousands separators, and returns None for 
    anything that cannot be parsed (including "" and "n/a").
    """
    if not isinstance(s, str):
        return None

    # Normalize the string: remove '$' and ','
    cleaned_s = s.strip().lstrip('$').replace(',', '')

    # Check for common non-numeric indicators before attempting conversion
    if not cleaned_s or cleaned_s.lower() in ("n/a", "none"):
        return None

    try:
        return float(cleaned_s)
    except ValueError:
        # Catches cases where the remaining string is still not a valid float (e.g., "abc")
        return None
